                        borderRadius: '20px',
                        width: '90%',
                        maxWidth: '400px',
                        padding: '24px',
                        boxShadow: '0 20px 50px rgba(0, 0, 0, 0.8), 0 0 30px rgba(139, 92, 246, 0.2)',
